/**
 * DIN-14021 regulation-table seed builders (Plan 3 Task 25, 2026-09-18).
 *
 * SR-1: every seeded value and every `verbatim_quote` was read in this session
 * from the bilingual (DE / EN) markdown transcript
 * `Desktop\Guidelines\DWA DIN Scribd\DIN-14021\DIN-EN-ISO-14021.md` (2122 lines;
 * DIN EN ISO 14021:2016). The GERMAN column is the primary span (prod labels are
 * German); the spans live in `regulation-tables-quotes-din14021.ts` (generated by
 * line range, never retyped); the line range is in each span's name. A markdown
 * transcript is the SR-1 source per owner ruling 2026-09-05 (VC grade) — every
 * table whose every row quote is lifted ships `verification_status: 'md_verified'`.
 * Verified by `scripts/regulation-tables/verify-regulation-tables.ts din14021
 * "<transcript>"`. Emitted as `20260917102500_regulation_tables_seed_din14021.sql`
 * (no earlier DIN-14021 table seed exists — nothing superseded).
 *
 * Edition: the title page prints "(ISO 14021:2016);" / "Deutsche und Englische
 * Fassung EN ISO 14021:2016" (L8–L9); prod `standards.version` is
 * "2016 (ISO 14021:2016); EN ISO 14021:2016" (read-only 2026-09-18) → token `'2016'`.
 *
 * The standard prints NO numeric value table (inventory §1 confirmed in-session:
 * `grep -n "Tabelle [0-9]"` hits only the bibliographic pointer "IPCC … Tabelle 2.14"
 * L570 / L590 — see the report §3). Its lookups are TEXT classifications:
 *   - CLAIMMAP — one row per prod `selected_claim_type` token (23, D-1 / G-A3: the
 *     keys ARE the captured tokens), each carrying the §7.x clause it maps to, the
 *     printed condition sentence ("darf nur … wenn" / "darf nicht … wenn" / the
 *     binding "muss" sentence) and `numeric_block`, a STRUCTURAL classifier (which
 *     numeric block of the register the type needs: none / recovered_energy /
 *     recycled_content / reduced_resource / renewable_material / renewable_energy /
 *     carbon — an executor token, recorded as structure, never a printed cell);
 *     `comparative_by_clause` = the printed "Weil … eine vergleichende Aussage ist,
 *     müssen die Anforderungen von 6.3 erfüllt sein" (asserted per row).
 *   - S6_5_3 — the seven printed minimum-documentation items a) – g) (§6.5.3).
 *   - S5_3_5_10 — the eight general-requirement clauses 5.3 … 5.10 as printed
 *     headings + one binding sentence each.
 * Policy `locked` on all three (§7.1.1 L1059 "darf nicht … abgeschwächt werden",
 * §7.6.3 a) "darf nur erfolgen, wenn", §6.5.3 "müssen Folgendes enthalten").
 *
 * Judgment items (all on the sign-off sheet, nothing corrected):
 *   - din14021-J-1: the four §7.8.1.1 TERM tokens (pre_consumer_material /
 *     post_consumer_material / recycled_material / recovered_reclaimed_material)
 *     are definitions, not claim types with their own Voraussetzungen; the two
 *     waste tokens map to the recycled_content block (7.8.1.1 a): "nur Abfälle vor
 *     Gebrauch und Abfälle nach Gebrauch"), the two material tokens to `none` with
 *     their printed definition as the condition text.
 *   - din14021-J-2: `other` (prod "sonstige Umweltaussage") maps to §5.1 L757 — the
 *     printed sentence that names "eine sonstige Umweltaussage"; no §7 clause.
 *   - din14021-J-3: the 5.8 / 5.9 / 5.10 rows of S5_3_5_10 carry ONE binding
 *     sentence each (5.8.5 L878 / 5.9.2 L884 / 5.10.2.4 L910) — the clause prints several.
 */
import type { RegulationTable, RegulationRow } from './regulation-tables';
import { Q } from './regulation-tables-quotes-din14021';

const STD = 'DIN-14021';
export const DIN14021_EDITION = '2016';
const ED = DIN14021_EDITION;
const STATUS = 'md_verified' as const; // markdown transcript, every row quote lifted (VC grade by ruling)

const collapse = (s: string) => s.replace(/\s+/g, ' ').trim();
/** Build-time SR-1 guard: every seeded cell text must be printed inside the named span (whitespace-collapsed). */
function inSpan(quote: string, cell: string | null, where: string): void {
  if (cell !== null && !collapse(quote).includes(collapse(cell))) throw new Error(`${where}: cell "${cell}" is not inside its verbatim span`);
}
/** A printed heading line `\subsection*{7.14 Erneuerbares Material}` / `\section*{1) Abfall vor Gebrauch}` → its text without the LaTeX wrapper. */
export function headingText(line: string): string {
  const m = line.match(/^\\(?:sub)?section\*\{(.*)\}$/);
  if (!m) throw new Error(`not a heading line: ${line}`);
  return m[1];
}

/** The structural classifier of the register's numeric block (executor tokens, not printed). */
export const NUMERIC_BLOCKS = ['none', 'recovered_energy', 'recycled_content', 'reduced_resource', 'renewable_material', 'renewable_energy', 'carbon'] as const;
export type NumericBlock = (typeof NUMERIC_BLOCKS)[number];

// ---------------------------------------------------------------------------
// CLAIMMAP — §7.2 – §7.17 (+ §5.1 for `other`): one row per prod `selected_claim_type` token (23, captured
// 2026-09-18; the register's lookup_key offers exactly these). `clause` = the sub-clause whose sentence is
// `condition_text` (the printed "darf nur … wenn" / "darf nicht … wenn" / binding "muss" sentence, lifted as
// the row quote); `label_de` = the printed term (the §7.1 NOTE list L1063–L1076 for 7.2–7.13, the printed
// headings for the rest — asserted inside their spans); `comparative_by_clause` = the row's sentence prints
// "vergleichende Aussage … Anforderungen von 6.3" (asserted). `numeric_block` is STRUCTURE (which register
// columns the type needs). Policy locked: §7.1.1 L1059 + §7.6.3 a) L1297.
// ---------------------------------------------------------------------------
type ClaimRow = { claim_type: string; clause: string; block: NumericBlock; quote: string; label: string; labelSpan: string; comparative: boolean };
const C = (claim_type: string, clause: string, block: NumericBlock, quote: string, label: string, labelSpan: string, comparative = false): ClaimRow =>
  ({ claim_type, clause, block, quote, label, labelSpan, comparative });
export const CLAIMMAP_ROWS: readonly ClaimRow[] = [
  C('compostable', '7.2.2.1', 'none', Q.L1104_1107, 'kompostierbar', Q.L1063_1074),
  C('degradable', '7.3.2.1 a)', 'none', Q.L1155_1157, 'abbaubar', Q.L1063_1074),
  C('designed_for_disassembly', '7.4.2.1', 'none', Q.L1192, 'zerlegbar konstruiert', Q.L1063_1074),
  C('extended_life_product', '7.5.2.1', 'none', Q.L1250, 'verlängertes Produktleben', Q.L1063_1074, true),
  C('recovered_energy', '7.6.3 a)', 'recovered_energy', Q.L1296_1298, 'zurückgewonnene Energie', Q.L1063_1074),
  C('recyclable', '7.7.2', 'none', Q.L1336_1340, 'recyclingfähig', Q.L1063_1074),
  C('recycled_content', '7.8.2.1', 'recycled_content', Q.L1449_1450, 'Recyclatgehalt', Q.L1063_1074),
  C('pre_consumer_material', '7.8.1.1 a) 1)', 'recycled_content', Q.L1382, headingText(Q.L1384), Q.L1384),
  C('post_consumer_material', '7.8.1.1 a) 2)', 'recycled_content', Q.L1382, headingText(Q.L1410), Q.L1410),
  C('recycled_material', '7.8.1.1 b)', 'none', Q.L1416, headingText(Q.L1414), Q.L1414),
  C('recovered_reclaimed_material', '7.8.1.1 c)', 'none', Q.L1420, headingText(Q.L1418), Q.L1418),
  C('reduced_energy_consumption', '7.9.2.1', 'none', Q.L1508_1509, 'reduzierter Energieverbrauch', Q.L1063_1074, true),
  C('reduced_resource_use', '7.10.2.4', 'reduced_resource', Q.L1551, 'reduzierter Ressourcenverbrauch', Q.L1063_1074, true),
  C('reduced_water_consumption', '7.11.2.1', 'none', Q.L1585, 'reduzierter Wasserverbrauch', Q.L1063_1074, true),
  C('reusable', '7.12.2.2', 'none', Q.L1646_1648, headingText(Q.L1616).replace(/^7\.12\.1\.1 /, ''), Q.L1616),
  C('refillable', '7.12.2.2', 'none', Q.L1646_1648, headingText(Q.L1620).replace(/^7\.12\.1\.2 /, ''), Q.L1620),
  C('waste_reduction', '7.13.2.1', 'none', Q.L1683, 'Abfallminderung', Q.L1063_1074, true),
  C('renewable_material', '7.14.2', 'renewable_material', Q.L1719_1721, headingText(Q.L1709).replace(/^7\.14 /, ''), Q.L1709),
  C('renewable_energy', '7.15.2', 'renewable_energy', Q.L1763, headingText(Q.L1753).replace(/^7\.15 /, ''), Q.L1753),
  C('sustainable', '7.16.1', 'none', Q.L1801, headingText(Q.L1797).replace(/^7\.16 /, ''), Q.L1797),
  C('product_carbon_footprint', '7.17.2.2', 'carbon', Q.L1845, headingText(Q.L1812).replace(/^7\.17\.2 /, ''), Q.L1812),
  C('carbon_neutral', '7.17.3.2', 'carbon', Q.L1856, '„CO2-neutral“', Q.L1856),
  C('other', '5.1', 'none', Q.L757, 'sonstige Umweltaussage', Q.L757),
];
/** The printed "comparative ⇒ 6.3" fragment every `comparative_by_clause` row must carry (§7.5.2.1 / 7.9.2.1 / 7.10.2.4 / 7.11.2.1 / 7.13.2.1). */
export const COMPARATIVE_FRAGMENT = 'müssen die Anforderungen von 6.3 erfüllt sein';

export function claimmapAsTable(): RegulationTable {
  inSpan(Q.L1059, 'darf nicht durch Verwendung ähnlicher Begriffe abgeschwächt werden', 'CLAIMMAP policy');
  inSpan(Q.L1297, 'darf nur erfolgen, wenn', 'CLAIMMAP policy');
  const rows: RegulationRow[] = CLAIMMAP_ROWS.map((r, i) => {
    inSpan(r.labelSpan, r.label, `CLAIMMAP ${r.claim_type} label`);
    if (r.comparative) inSpan(r.quote, COMPARATIVE_FRAGMENT, `CLAIMMAP ${r.claim_type} comparative`);
    else if (collapse(r.quote).includes(COMPARATIVE_FRAGMENT)) throw new Error(`CLAIMMAP ${r.claim_type}: the row prints the 6.3 fragment but is not flagged comparative`);
    if (!(NUMERIC_BLOCKS as readonly string[]).includes(r.block)) throw new Error(`CLAIMMAP ${r.claim_type}: unknown block ${r.block}`);
    return { row_key: r.claim_type, keys: { claim_type: r.claim_type }, group_label: null, label_de: r.label, order_index: i,
      values: { clause: r.clause, numeric_block: r.block, condition_text: collapse(r.quote), comparative_by_clause: r.comparative }, verbatim_quote: r.quote };
  });
  return { standard_code: STD, edition: ED, table_code: 'CLAIMMAP', title_de: 'Aussagetyp → Abschnitt 7 (Voraussetzung, Bewertungsverfahren) — je Aussagetyp die gedruckte Bedingung und der benötigte Zahlenblock', clause_reference: '§7.2–§7.17 (§5.1 für sonstige Umweltaussagen)', page_ref: null,
    key_columns: ['claim_type'],
    value_columns: [{ name: 'clause', type: 'string' }, { name: 'numeric_block', type: 'enum' }, { name: 'condition_text', type: 'string' }, { name: 'comparative_by_clause', type: 'boolean' }],
    override_policy: 'locked',
    override_quote: `${Q.L1059} — ${Q.L1297}`,
    verification_status: STATUS, rows };
}

// ---------------------------------------------------------------------------
// S6_5_3 — §6.5.3 (L1032–L1038, g) at L1054): "Die Mindestangaben, die nach 6.2 zu dokumentieren und aufzubewahren
// sind, müssen Folgendes enthalten:" a) – g). One row per printed item; `letter` the printed marker, `text` the
// item without it. Keys = the item letters; the created `documentation_items` select_many (-04) offers the
// printed lines (`label_de` of these rows) as its options (the checklist renders enum_values[].value —
// m820_2 trap 1). Policy locked ("müssen … enthalten").
// ---------------------------------------------------------------------------
export const S6_5_3_ROWS = [
  { item: 'a', quote: Q.L1033 }, { item: 'b', quote: Q.L1034 }, { item: 'c', quote: Q.L1035 }, { item: 'd', quote: Q.L1036 },
  { item: 'e', quote: Q.L1037 }, { item: 'f', quote: Q.L1038 }, { item: 'g', quote: Q.L1054 },
] as const;
/** The printed item text without its "x)" marker (whitespace-collapsed). */
export function itemText(item: string, quote: string): string {
  const m = collapse(quote).match(/^([a-g])\)\s+(.*)$/);
  if (!m || m[1] !== item) throw new Error(`S6_5_3 ${item}: span does not start with "${item})"`);
  return m[2];
}
export function s653AsTable(): RegulationTable {
  inSpan(Q.L1032, 'müssen Folgendes enthalten', 'S6_5_3 policy');
  const rows: RegulationRow[] = S6_5_3_ROWS.map((r, i) => {
    const text = itemText(r.item, r.quote);
    inSpan(r.quote, text, `S6_5_3 ${r.item}`);
    return { row_key: r.item, keys: { item: r.item }, group_label: null, label_de: `${r.item}) ${text}`, order_index: i,
      values: { letter: `${r.item})`, text }, verbatim_quote: r.quote };
  });
  return { standard_code: STD, edition: ED, table_code: 'S6_5_3', title_de: 'Mindestangaben der Dokumentation a) – g) (§6.5.3 „müssen Folgendes enthalten“)', clause_reference: '§6.5.3', page_ref: null,
    key_columns: ['item'],
    value_columns: [{ name: 'letter', type: 'string' }, { name: 'text', type: 'string' }],
    override_policy: 'locked',
    override_quote: Q.L1032,
    verification_status: STATUS, rows };
}

// ---------------------------------------------------------------------------
// S5_3_5_10 — §5.3 … §5.10 (L781–L910): the eight general-requirement clauses as printed headings + one
// binding sentence each (the row quote). Keys = clause tokens; the created `general_requirements_items`
// select_many (-03) offers the printed headings (`heading`) as its options. Policy locked (5.3 "darf nicht
// gemacht werden", 5.4 "darf nur gemacht werden, wenn", 5.5 "darf keine … gemacht werden", 5.6 "müssen",
// 5.7 "sind Gegenstand aller Anforderungen", 5.8.5 / 5.9.2 / 5.10.2.4 "dürfen nur" / "dürfen nicht" / "darf nur").
// ---------------------------------------------------------------------------
export const S5_3_5_10_ROWS = [
  { clause: '5_3', printed: '5.3', headingSpan: Q.L781, quote: Q.L783 },
  { clause: '5_4', printed: '5.4', headingSpan: Q.L787, quote: Q.L789 },
  { clause: '5_5', printed: '5.5', headingSpan: Q.L793, quote: Q.L795 },
  { clause: '5_6', printed: '5.6', headingSpan: Q.L797, quote: Q.L799 },
  { clause: '5_7', printed: '5.7', headingSpan: Q.L821, quote: Q.L823 },
  { clause: '5_8', printed: '5.8', headingSpan: Q.L873, quote: Q.L878 },
  { clause: '5_9', printed: '5.9', headingSpan: Q.L882, quote: Q.L884 },
  { clause: '5_10', printed: '5.10', headingSpan: Q.L900, quote: Q.L910 },
] as const;
export function s53510AsTable(): RegulationTable {
  const rows: RegulationRow[] = S5_3_5_10_ROWS.map((r, i) => {
    const heading = headingText(r.headingSpan);
    if (!heading.startsWith(`${r.printed} `)) throw new Error(`S5_3_5_10 ${r.clause}: heading "${heading}" does not start with ${r.printed}`);
    inSpan(r.headingSpan, heading, `S5_3_5_10 ${r.clause} heading`);
    return { row_key: r.clause, keys: { clause: r.clause }, group_label: null, label_de: heading, order_index: i,
      values: { clause_printed: r.printed, heading, requirement_text: collapse(r.quote) }, verbatim_quote: r.quote };
  });
  return { standard_code: STD, edition: ED, table_code: 'S5_3_5_10', title_de: 'Anforderungen an alle umweltbezogenen Anbietererklärungen — die Abschnitte 5.3 bis 5.10 als Prüfliste', clause_reference: '§5.3–§5.10', page_ref: null,
    key_columns: ['clause'],
    value_columns: [{ name: 'clause_printed', type: 'string' }, { name: 'heading', type: 'string' }, { name: 'requirement_text', type: 'string' }],
    override_policy: 'locked',
    override_quote: `${Q.L823} — ${Q.L783}`,
    verification_status: STATUS, rows };
}

/** The live DIN-14021 set (three text tables). */
export function din14021SeedTables(): RegulationTable[] {
  return [claimmapAsTable(), s653AsTable(), s53510AsTable()];
}
